function countBelowZero(grid: number[][]): number {
  let count = 0;
  for (const row of grid) {
    let lo = 0, hi = row.length; // first index with row[i] < 0
    while (lo < hi) {
      const mid = (lo + hi) >> 1;
      if (row[mid] < 0) hi = mid; else lo = mid + 1;
    }
    count += row.length - lo;
  }
  return count;
}

