function countBelowZero(grid: number[][]): number {
  const n = grid[0].length;
  let col = n - 1, count = 0;
  for (const row of grid) {
    while (col >= 0 && row[col] < 0) col--;
    count += n - 1 - col;
  }
  return count;
}

